from sqlalchemy import *
from sqlalchemy.types import Uuid
metadata=MetaData()
definitions=Table("universe_definitions",metadata,Column("universe_id",Uuid,primary_key=True),Column("name",String,nullable=False),Column("kind",String,nullable=False),Column("source",String,nullable=False),Column("version",String,nullable=False),Column("rule_description",String,nullable=False),Column("max_change_ratio",Numeric,nullable=False),Column("max_staleness_days",Integer,nullable=False),UniqueConstraint("name","version"))
batches_table=Table("universe_batches",metadata,Column("batch_id",Uuid,primary_key=True),Column("universe_id",Uuid,ForeignKey("universe_definitions.universe_id"),nullable=False),Column("source_batch_id",String,nullable=False),Column("effective_date",Date,nullable=False),Column("announced_at",DateTime(timezone=True),nullable=False),Column("available_at",DateTime(timezone=True),nullable=False),Column("payload_hash",String,nullable=False),Column("status",String,nullable=False),Column("member_count",Integer,nullable=False),UniqueConstraint("universe_id","source_batch_id"),CheckConstraint("available_at >= announced_at"))
memberships=Table("universe_memberships",metadata,Column("membership_id",Uuid,primary_key=True),Column("universe_id",Uuid,ForeignKey("universe_definitions.universe_id"),nullable=False),Column("instrument_id",Uuid,nullable=False),Column("valid_from",Date,nullable=False),Column("valid_to",Date),Column("announced_at",DateTime(timezone=True),nullable=False),Column("available_at",DateTime(timezone=True),nullable=False),Column("source_batch_id",String,nullable=False),CheckConstraint("valid_to IS NULL OR valid_to > valid_from"),CheckConstraint("available_at >= announced_at"))
snapshots=Table("universe_snapshots",metadata,Column("snapshot_id",Uuid,primary_key=True),Column("universe_id",Uuid,ForeignKey("universe_definitions.universe_id"),nullable=False),Column("decision_at",DateTime(timezone=True),nullable=False),Column("data_snapshot_id",Uuid,nullable=False),Column("member_ids",JSON,nullable=False),Column("member_hash",String,nullable=False),Column("source_batch_ids",JSON,nullable=False))
classifications=Table("classification_memberships",metadata,Column("classification_id",Uuid,primary_key=True),Column("instrument_id",Uuid,nullable=False),Column("provider",String,nullable=False),Column("system",String,nullable=False),Column("version",String,nullable=False),Column("level",Integer,nullable=False),Column("code",String,nullable=False),Column("name",String,nullable=False),Column("valid_from",Date,nullable=False),Column("valid_to",Date),Column("available_at",DateTime(timezone=True),nullable=False))
quality=Table("universe_quality_results",metadata,Column("result_id",Uuid,primary_key=True),Column("batch_id",Uuid,nullable=False),Column("code",String,nullable=False),Column("message",String,nullable=False),Column("source_code",String))
events=Table("universe_events",metadata,Column("event_id",Uuid,primary_key=True),Column("universe_id",Uuid,nullable=False),Column("batch_id",Uuid,nullable=False),Column("joined",JSON,nullable=False),Column("removed",JSON,nullable=False),Column("effective_date",Date,nullable=False),Column("occurred_at",DateTime(timezone=True),nullable=False))
